from taf.gnb.oam.coam.admin.exceptions import DataInconsistent


class InfoModelDistName(object):
    def __init__(self, dist_name):

        if not dist_name:
            raise DataInconsistent("Dist name {} cannot be empty or string incompatible.")

        self.dist_name = dist_name

        try:
            self.conf_name, self.configuration_class_name, self.class_name, self.index = self.__get_dist_path_info()

        except (ValueError, IndexError):
            error_msg = "Dist Name {} data contains has incorrect distName"
            raise DataInconsistent(error_msg.format(self.dist_name))

    def __get_dist_path_info(self):
        """
        distName example: /MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-10191/NRBTS_A-1/NRCELL_A-1

        :return: Out of NRCELL_A-1: Conf name ie. NRCELL-1 , Index of object ie. 1 , Class name ie. NRCELL_A ,NRCELL_
        """
        object_name = self.dist_name.split("/")[-1]

        configuration_class_name = self.__get_configuration_class_name(object_name)
        class_name = self.__get_class_name(object_name)
        index = self.__get_index(object_name)
        configuration_name = self.__get_conf_name(configuration_class_name, index)

        return configuration_name, configuration_class_name, class_name, index

    def __get_configuration_class_name(self, object_name):
        return object_name.split("_")[0]

    def __get_class_name(self, object_name):
        return object_name.split("-")[0]

    def __get_index(self, object_name):
        return int(object_name.split("-")[-1])

    def __get_conf_name(self, configuration_class_name, index):
        return "{conf_class_name}-{index}".format(conf_class_name=configuration_class_name, index=index)


class InfoModelObjectField(object):
    def __init__(self, name, not_null=False):
        """

        :param str name: String name of the field in infomodel structure
        """
        self.name = name
        self.not_null = not_null


class InfoModelObject(object):
    """
    _R MO	- Runtime view object defined by external parties: NIDD, ADMIN, SYSADAPTER.
    _M MO	- Runtime view object defined by a manager. Used for internal OAM communication.
    _L MO	- Objects created by services. Often referred to as HW objects.
    _A MO	- Objects from network plan. Defined in NIDD without “_A” suffix.
    _NOTIF	- Object created by service, used to notify manager or indicator about a needed action.
    """
    class_name = None
    dist_name = None
    object_index = None
    conf_name = None
    conf_class_name = None

    def __init__(self, dist_name):
        dist_object = InfoModelDistName(dist_name=dist_name)

        self.dist_name = dist_object.dist_name
        self.class_name = dist_object.class_name
        self.object_index = dist_object.index
        self.conf_name = dist_object.conf_name
        self.conf_class_name = dist_object.configuration_class_name

        self.__check_not_null()

    def __check_not_null(self):
        for attribute_name, attribute_field in self.__get_infomodel_class_attributes():
            if attribute_field.not_null is True:
                attribute_value = getattr(self, attribute_name)
                if attribute_value is None or attribute_value == "":
                    error_msg = "{class_name} object attribute {attribute_name} is not allowed to be empty, but its provided value is empty."
                    raise DataInconsistent(error_msg.format(
                        class_name=self.__class__.__name__,
                        attribute_name=attribute_name,
                    ))

    @classmethod
    def __get_infomodel_class_attributes(cls):
        for attribute_name in dir(cls):
            attribute_field = getattr(cls, attribute_name)

            if not isinstance(attribute_field, InfoModelObjectField):
                continue

            yield attribute_name, attribute_field

    @classmethod
    def from_object_dict(cls, data):
        """
        Generic mechanism to create Infomodel Objects based on data,
        subclassess need to implement InfomodelObject interface

        :param dict data: Data of given infomodel
        :return InfoModelObject: Returns instance of subclass of InfomodelObject.
        """
        dist_name = ""
        try:
            dist_name = data['distName']
            parameters = data['parameters']
            object_attributes = dict()

            for attribute_name, attribute_field in cls.__get_infomodel_class_attributes():
                object_attributes[attribute_name] = parameters[attribute_field.name]

        except KeyError as e:
            error_msg = "Dist name {} data provided by M-plane is inconsistent or faulty. Error on {}"
            raise DataInconsistent(error_msg.format(dist_name, e))

        return cls(
            dist_name=dist_name,
            **object_attributes)

    def to_dict(self):
        """
        Serialize to dictionary structure.

        :return dict: Object as dict, with infomodel data parameters.
        """
        dict_data = dict()
        dict_data["parameters"] = dict()

        try:
            for attribute_name in dir(self):
                attribute_value = getattr(self, attribute_name)

                object_type = type(self)
                model_field = getattr(object_type, attribute_name)
                if not isinstance(model_field, InfoModelObjectField) or attribute_name.startswith("_"):
                    continue
                parameter_name = model_field.name

                dict_data["parameters"][parameter_name] = attribute_value
            dict_data["distName"] = self.dist_name

        except AttributeError as e:
            error_msg = "{} attributes that is being serialized is not consistent. Error on {}"
            raise DataInconsistent(error_msg.format(self.class_name, e))

        return dict_data
